// API названия полей/тостов Jinx UI сверены по README лишь частично: JxButton точно есть,
// JxInput/JxToast взяты по документированному контракту value+onValueChange / open+onOpenChange — сверь с типами пакета.
import { useState, type FormEvent } from 'react';
import { JxButton, JxInput, JxToast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [isToastOpen, setIsToastOpen] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email.trim()) return;
    setEmail('');
    setIsToastOpen(true);
  };

  return (
    <form
      className="jx-stack"
      onSubmit={handleSubmit}
      style={{ gap: 'var(--jx-space-3)', maxWidth: 'var(--jx-size-sm)' }}
    >
      <JxInput
        type="email"
        name="email"
        required
        label="Электронная почта"
        placeholder="you@example.com"
        value={email}
        onValueChange={setEmail}
      />
      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>
      <JxToast
        open={isToastOpen}
        onOpenChange={setIsToastOpen}
        placement="bottom-right"
        title="Готово"
      >
        Письмо отправлено на указанный адрес.
      </JxToast>
    </form>
  );
}

